// Entry point of the {{domain}} domain service. Generated by `tecton-admin generate domain`.
// Routes come from tecton.yaml; actions answer 501 until you implement them.
//
// Every action that is not public verifies its Bearer token itself (Zero Trust, AD-7), from the
// environment: TECTON_JWKS_URL (the JWKS of the Auth service, https outside development),
// TECTON_AUTH_ISSUER, TECTON_AUTH_AUDIENCE, TECTON_ENV (development allows an http JWKS URL) and
// TECTON_JWKS_CA_FILE (optional CA for the JWKS). A missing setting stops the service at startup.
import { fileURLToPath } from 'node:url';
import { startDomainServer } from '@tecton/core';

const manifestPath = fileURLToPath(new URL('../tecton.yaml', import.meta.url));

/** PORT from the environment (default 3000); anything but an integer in 0-65535 stops the service. */
function portFromEnv(value: string | undefined): number {
  if (value === undefined || value.trim() === '') return 3000;
  const port = Number(value);
  if (!Number.isInteger(port) || port < 0 || port > 65535) {
    throw new Error(`PORT must be an integer between 0 and 65535, got "${value}"`);
  }
  return port;
}

const port = portFromEnv(process.env['PORT']);
// Loopback by default; set HOST=0.0.0.0 to accept connections from other machines or containers.
const host = process.env['HOST'] || '127.0.0.1';

const app = await startDomainServer({ manifestPath, port, host, logger: true, env: process.env });
app.log.info({ domain: '{{domain}}', host, port }, 'domain service started');

// Graceful shutdown: finish in-flight requests before exiting (docker stop, Ctrl+C).
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.once(signal, () => {
    app.log.info({ signal }, 'shutting down');
    app.close().then(
      () => process.exit(0),
      (error: unknown) => {
        app.log.error({ err: error }, 'shutdown failed');
        process.exit(1);
      },
    );
  });
}
